CREATE TABLE IF NOT EXISTS movies(id INTEGER PRIMARY KEY,title TEXT NOT NULL,year INTEGER,director TEXT NOT NULL,description TEXT NOT NULL,genres TEXT NOT NULL,cast_names TEXT NOT NULL,keywords TEXT NOT NULL,runtime INTEGER,language TEXT,rating REAL, votes INTEGER,poster TEXT);
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,username TEXT NOT NULL UNIQUE COLLATE NOCASE,email TEXT NOT NULL UNIQUE COLLATE NOCASE,password TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS entries(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),movie_id INTEGER NOT NULL REFERENCES movies(id),watched_on TEXT NOT NULL,score REAL CHECK(score BETWEEN 0 AND 5),review TEXT NOT NULL DEFAULT '',spoiler INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS shelves(user_id INTEGER NOT NULL REFERENCES users(id),movie_id INTEGER NOT NULL REFERENCES movies(id),kind TEXT NOT NULL CHECK(kind IN ('favorite','watchlist')),PRIMARY KEY(user_id,movie_id,kind));
CREATE INDEX IF NOT EXISTS entries_user ON entries(user_id,watched_on DESC);
CREATE INDEX IF NOT EXISTS entries_movie ON entries(movie_id);
CREATE INDEX IF NOT EXISTS movies_year ON movies(year);
CREATE TABLE IF NOT EXISTS app_meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS watch_sessions(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),title TEXT NOT NULL,movie_a INTEGER NOT NULL REFERENCES movies(id),movie_b INTEGER NOT NULL REFERENCES movies(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK(movie_a != movie_b));
CREATE INDEX IF NOT EXISTS sessions_user ON watch_sessions(user_id,created_at DESC);
